{
  "content": "<!-- src/components/JobCard.jsx -->

import React from 'react';

const JobCard = ({ job }) => {
  const { id, title, company, location, workplace, salary, posted, match, skills, gap, color } = job;

  return (
    <div className="job-card">
      <div className="job-top">
        <div className={`company-mark ${color ? `large` : ``}`}></div>
        <div className="job-heading">
          <h3>{title}</h3>
          <p className="text-muted small">{company}</p>
        </div>
      </div>

      <div className="job-meta">
        <span>{location}</span>
        <span>{workplace}</span>
        <span>{salary}</span>
        <span>Posted {posted} ago</span>
      </div>

      <div className="job-skills">
        <p className="eyebrow">Matched Skills</p>
        {skills.map((skill, index) => (
          <span key={index} className="chip selected">{skill}</span>
        ))}
      </div>

      <div className="job-bottom">
        <button className={`icon-button ${gap ? `saved` : ``}`} aria-label="Save Job">
          <span className="material-symbols-outlined" data-icon={gap ? `bookmark` : `bookmark_border`}>bookmark</span>
        </button>

        <a href={`/job/${id}`} className="text-button primary">View Details</a>
      </div>
    </div>
  );
};

export default JobCard;"
}
